import type { FilteredUpdate, MessageBody, MessageCallbackUpdate, MessageCreatedUpdate, MessageEditedUpdate, Update, UpdateType } from '../../network/api';
import type { Guard } from '../../types';
type UpdateFilter = UpdateType | Guard<Update>;
/** Определяет тип события после проверки по имени или type guard. */
type FilteredBy<Filter> = Filter extends UpdateType ? FilteredUpdate<Filter> : Filter extends Guard<Update, infer U> ? U : never;
type UnionToIntersection<Union> = (Union extends unknown ? (value: Union) => void : never) extends (value: infer Intersection) => void ? Intersection : never;
export declare const createdMessageBodyHas: <Keys extends Array<keyof MessageBody>>(...keys: Keys) => (update: Update) => update is MessageCreatedUpdate;
export declare const messageEdited: (update: Update) => update is MessageEditedUpdate;
export declare const messageCallback: (update: Update) => update is MessageCallbackUpdate;
/** Создаёт guard, которому достаточно совпадения хотя бы с одним фильтром. */
export declare const anyOf: <Filters extends UpdateFilter[]>(...filters: Filters) => Guard<Update, FilteredBy<Filters[number]>>;
/** Создаёт guard, для которого должны одновременно выполниться все фильтры. */
export declare const allOf: <Filters extends UpdateFilter[]>(...filters: Filters) => Guard<Update, UnionToIntersection<FilteredBy<Filters[number]>> & Update>;
export {};
